<?php
 namespace Pterodactyl\Console\Commands\Dezerx; use Illuminate\Console\Command; use Pterodactyl\Services\Dezerx\Addons; use Pterodactyl\Models\Dezerx\DriveBackup; use Pterodactyl\Jobs\Dezerx\CopyBackupToDrive; use Pterodactyl\Services\Dezerx\Drive\GoogleDrive; class RunDriveBackups extends Command { protected $signature = 'dezerx:drive-backups'; protected $description = 'Copy due server backups into their connected Google Drives.'; public function handle(): int { if (!Addons::get(Addons::DRIVE_BACKUPS)['enabled'] || !GoogleDrive::configured()) { return 0; } $queued = 0; DriveBackup::query() ->where('interval_hours', '>', 0) ->with('server') ->chunkById(100, function ($links) use (&$queued) { foreach ($links as $link) { if ($link->last_state === 'running' || !$link->isDue()) { continue; } if ($link->server === null || !Addons::appliesTo(Addons::DRIVE_BACKUPS, $link->server)) { continue; } CopyBackupToDrive::dispatch($link); $queued++; } }); $this->line("Queued {$queued} Drive " . ($queued === 1 ? 'copy.' : 'copies.')); return 0; } } 